    "answer": "Profesi Auditor K3 Auditor Eksternal SMK3 Kemnaker RI adalah peran profesional HSE yang bertugas mengelola pengawasan dan penerapan standar keselamatan di sektor Auditor Eksternal SMK3 Kemnaker RI dengan kisaran gaji Rp 6.000.000 - Rp 14.000.000.",
