    "blocks": [
      {
        "heading": "Peran & Tanggung Jawab Profesi Auditor K3 Auditor Eksternal SMK3 Kemnaker RI",
        "paragraphs": [
          "Posisi Profesi Auditor K3 Auditor Eksternal SMK3 Kemnaker RI memegang tanggung jawab fundamental dalam memimpin dan mengoordinasikan praktik keselamatan kerja di sektor Auditor Eksternal SMK3 Kemnaker RI.",
          "Tugas utama meliputi pengawasan implementasi SOP keselamatan, penegakan disiplin pemakaian APD, pemantauan izin kerja aman, dan pelaporan berkala kepada manajemen."
        ]
      },
      {
        "heading": "Wewenang & Lingkup Kerja",
        "paragraphs": [
          "Tenaga profesional pada posisi ini berwenang untuk:"
        ],
        "bullets": [
          "Menghentikan pekerjaan yang terindikasi membahayakan jiwa (Stop Work Authority)",
          "Melakukan investigasi insiden dan nearmiss di area tanggung jawabnya",
          "Menyusun analisis risiko (JSA/HIRADC) bersama tim teknis lapangan",
          "Memverifikasi kesiapan alat pelindung diri dan sarana tanggap darurat"
        ]
      },
      {
        "heading": "Kisaran Gaji & Jenjang Karir",
        "paragraphs": [
          "Estimasi penghasilan untuk Profesi Auditor K3 Auditor Eksternal SMK3 Kemnaker RI di Indonesia berkisar antara Rp 6.000.000 - Rp 14.000.000, dengan potensi kenaikan seiring bertambahnya pengalaman proyek, kepemilikan sertifikasi kompetensi BNSP/Kemnaker, dan lisensi sektoral."
        ]
      },
      {
        "heading": "Kualifikasi & Sertifikasi yang Diperlukan",
        "paragraphs": [
          "Persyaratan umum meliputi pemahaman regulasi K3 nasional, sertifikat kompetensi terkait, serta kemampuan komunikasi kepemimpinan keselamatan yang efektif."
        ]
      }
    ],
    "faqs": [
      {
        "question": "Apa sertifikasi yang paling dibutuhkan untuk posisi Profesi Auditor K3 Auditor Eksternal SMK3 Kemnaker RI?",
        "answer": "Sertifikasi yang direkomendasikan mencakup Ahli K3 Umum, sertifikat kompetensi pengawas BNSP, serta sertifikasi teknis spesifik sektor terkait."
      },
      {
        "question": "Apakah posisi Profesi Auditor K3 Auditor Eksternal SMK3 Kemnaker RI memiliki wewenang menghentikan pekerjaan bahaya?",
        "answer": "Ya, seluruh personel HSE memiliki Stop Work Authority apabila menemukan kondisi tidak aman (unsafe condition) atau tindakan tidak aman (unsafe act) kritis."
      }
    ],
